class TaskResult:
    def __init__(self, task: str, workspace: str):
        self.task = task
        self.workspace = workspace
        self.files = {}
        self.plan = None
        self.entry_point = None
        self.started_at = time.time()
        self.finished_at = None

    def set_file(self, filename, code, status, attempts, verdict=None):
        self.files[filename] = {
            "code": code,
            "status": status,
            "attempts": attempts,
            "verdict": verdict,
        }

    def ok_count(self):
        return sum(1 for f in self.files.values() if f["status"] == "done")

    def fail_count(self):
        return sum(1 for f in self.files.values() if f["status"] == "failed")

    def duration(self):
        end = self.finished_at or time.time()
        return round(end - self.started_at, 1)

    def summary(self):
        lines = [
            f"Задача: {self.task[:100]}",
            f"Workspace: {self.workspace}",
            f"Время: {self.duration()}с",
            f"Файлов: {len(self.files)} (готово: {self.ok_count()}, "
            f"провалено: {self.fail_count()})",
            "",
            "Файлы:",
        ]
        for fn, info in self.files.items():
            icon = "✅" if info["status"] == "done" else "❌"
            v = f" [{info['verdict']}]" if info.get("verdict") else ""
            lines.append(f"  {icon} {fn} — попыток: {info['attempts']}{v}")
        return "\n".join(lines)

def _normalize_step(s, default_ext: str) -> dict:
    """Приводит элемент плана к единому виду."""
    if isinstance(s, str):
        return {
            "file": f"main{default_ext}",
            "action": s,
            "dependencies": [],
        }
    if not isinstance(s, dict):
        return None

    deps = s.get("dependencies", [])
    if not isinstance(deps, list):
        deps = []

    return {
        "file": (s.get("file") or s.get("filename")
                 or f"main{default_ext}"),
        "action": (s.get("action") or s.get("description")
                   or s.get("task") or "выполнить"),
        "dependencies": [str(d) for d in deps if d],
    }

