def _pick_best_gguf(files: list) -> dict:
    """
    Выбирает лучший .gguf.

    Логика:
    1. Если есть ЕДИНЫЕ файлы (не split) — берём из них приоритет Q4_K_M и т.д.
    2. Если только split — ищем группу Q4_K_M, возвращаем первую часть
       (остальные части pull_model найдёт и докачает сам).
    3. Fallback — минимальный по размеру.
    """
    if not files:
        return None

    patterns = ["q4_k_m", "q4_k_s", "q5_k_m", "q5_k_s",
                "q4_0", "q6_k", "q8_0", "q3_k_m", "q2_k"]

    # === Случай 1: единые файлы ===
    singles = [f for f in files if not _is_split(f["path"])]
    if singles:
        for pat in patterns:
            for f in singles:
                if pat in f["path"].lower():
                    return f
        # Нет известных квантизаций — берём самый маленький единый
        return min(singles, key=lambda x: x["size"] or 10 ** 18)

    # === Случай 2: только split ===
    # Группируем по базовому имени
    groups = {}
    for f in files:
        key = _split_group_key(f["path"])
        groups.setdefault(key, []).append(f)

    # Ищем группу с Q4_K_M
    for pat in patterns:
        for key, parts in groups.items():
            if pat in key.lower():
                # Возвращаем первую часть группы (pull_model докачает остальные)
                return sorted(parts, key=lambda x: x["path"])[0]

    # Нет известной квантизации — берём группу с наименьшим размером
    # первой части (обычно это разумная квантизация)
    smallest = min(files, key=lambda x: x["size"] or 10 ** 18)
    return smallest

