def _download_file(url: str, local_path: str, total: int,
                   on_progress=None, job=None,
                   repo_id: str = "",
                   part_idx: int = 1,
                   part_total: int = 1) -> tuple:
    """
    Скачивает один файл с докачкой.
    Возвращает (ok, downloaded_bytes, error).
    """
    downloaded = os.path.getsize(local_path) if os.path.exists(local_path) else 0

    if downloaded and total and downloaded >= total:
        return True, downloaded, ""

    try:
        headers = {}
        mode = "wb"
        if downloaded and total and downloaded < total:
            headers["Range"] = f"bytes={downloaded}-"
            mode = "ab"

        r = requests.get(url, stream=True, headers=headers,
                         **_req_kwargs(timeout=60))
        if r.status_code not in (200, 206):
            return False, downloaded, f"HTTP {r.status_code}"

        os.makedirs(MODELS_DIR, exist_ok=True)
        last_pct = -1
        with open(local_path, mode) as f:
            for chunk in r.iter_content(chunk_size=1024 * 1024):
                if job and job.cancelled:
                    return False, downloaded, "Отменено"
                if not chunk:
                    continue
                f.write(chunk)
                downloaded += len(chunk)
                if on_progress and total:
                    pct = int(downloaded * 100 / total)
                    if pct != last_pct:
                        part_label = (f" [{part_idx}/{part_total}]"
                                      if part_total > 1 else "")
                        on_progress(
                            repo_id, pct,
                            f"{downloaded // (1024 ** 2)}/"
                            f"{total // (1024 ** 2)} МБ{part_label}",
                        )
                        last_pct = pct
        return True, downloaded, ""
    except Exception as e:
        return False, downloaded, str(e)

